use canvas_core::{error_archive::{ErrorArchive as A,Error,Limits},remote_error::RemoteErrorLeaf,payload_codec::Value as V,human_readable_error::{extract_encoded_with,ARCHIVE_KEY},service_reply_error::ServiceReplyError,service_response::send_service_response_binary,service_reply_failure::{classify_service_observed_data_with,ReplyRepresentation,ServiceReplyFailure},binary_plist,settings_xpc::XpcValue};use std::collections::BTreeMap;
fn leaf(crash:bool,native:bool)->A{A::Leaf(RemoteErrorLeaf::from_dictionary(&BTreeMap::from([("errorType".into(),V::String("leaf".into())),("isPotentialCrash".into(),V::Boolean(crash)),("isNative".into(),V::Boolean(native))])).unwrap())}
fn main(){let archive=A::Wrapper{main:Box::new(leaf(true,true)),underlying:Box::new(leaf(false,false))};assert!(!archive.is_potential_crash());assert!(archive.is_native());let fields=archive.to_dictionary().unwrap();assert_eq!(A::from_dictionary_with_limits(&fields,Limits{nodes:2,depth:64}),Err(Error::Limit));assert_eq!(A::from_dictionary_with_limits(&fields,Limits{nodes:3,depth:1}).unwrap(),archive);
 let error=ServiceReplyError{domain:"owned".into(),code:i64::MIN,user_info:BTreeMap::from([(ARCHIVE_KEY.into(),V::Dictionary(fields))])};let mut wire=BTreeMap::new();assert_eq!(send_service_response_binary(true,None,Some(error.clone()),&mut wire,Some,|_|()),Some(()));let XpcValue::Data(bytes)=&wire["data"]else{panic!()};let(p,f)=classify_service_observed_data_with(Some(bytes),ReplyRepresentation::SerializedData,binary_plist::decode,||panic!());assert!(p.is_none());let Some(ServiceReplyFailure::Remote(restored))=f else{panic!()};assert_eq!(restored,error);assert_eq!(extract_encoded_with(&restored.user_info,A::from_dictionary),Some(archive));
 println!("PASS: WASI recursive wrapper, branch flags, shape budgets and full service-error archive round-trip");}
